UPDATE comparisons SET
  verdict='Oneisall and Wahl are both cordless clippers, making this the closest grooming comparison: the debate is approachable guards versus adjustable professional-style control.',
  content_json=JSON_OBJECT('decisionQuestion','Do you value beginner-friendly guard changes or finer blade adjustment and maintenance?','scope','Checked variants are Oneisall B01HRSZRXM and Wahl Bravura B00EVBXI5S; coat condition and pet tolerance remain hard boundaries.','controversy','A quieter or more adjustable clipper does not make a matted coat safe to clip. Heat, pulling, and skin condition can end the session.','decisionRule','Choose Oneisall for routine home trims and guard-led learning; choose Wahl when blade adjustment and maintenance are worth the extra technique.','evidenceNote','Confirm current variant, blade, charger, price, and availability on Amazon.com.')
WHERE slug='oneisall-vs-wahl-bravura';

UPDATE best_picks SET content_json=JSON_OBJECT('why','A cordless entry point with six guide combs and a rinsable blade for routine home trims.','notFor','Matted coats, professional daily workloads, or a pet that cannot tolerate clipping.','decision',JSON_OBJECT('headline','Start with control and tolerance','summary','The listing supports guard-led home trimming; it does not prove every coat can be clipped safely.','criteria',JSON_ARRAY('Coat condition','Guide-comb range','Noise and heat tolerance'),'boundary','Stop for pulling, heat, skin irritation, or distress.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Listing fit','body','The checked Oneisall ASIN identifies a rechargeable cordless kit with six guide combs and a removable rinsable blade.'),JSON_OBJECT('title','First session','body','Charge, fit a guard, run the motor away from the pet, and make short passes on a brushed coat.'),JSON_OBJECT('title','Tradeoff','body','A guard-led setup is approachable, but it still needs cleaning, blade checks, and realistic coat boundaries.'),JSON_OBJECT('title','Alternative','body','Choose Wahl Bravura when adjustable blade control and maintenance matter more than a simple guard workflow.')),'alternatives',JSON_ARRAY('Wahl Professional Animal Bravura','A professional groomer for close mats'),'evidenceNote','ASIN, image, and listing identity are verified on Amazon.com; dynamic price and stock should be checked live.') WHERE slug='best-quiet-grooming-clipper';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A large 27.5 x 44 inch pad with a stated runoff barrier edge for indoor dog coverage.','notFor','Households trying to eliminate disposable waste or floors where the target area is not covered by the pad.','decision',JSON_OBJECT('headline','Coverage is only useful when placement matches the accident','summary','The dimension and barrier are listing facts; actual leakage depends on placement, saturation, and pet behavior.','criteria',JSON_ARRAY('Usable floor area','Pack usage per week','Edge and runoff risk'),'boundary','If the pad saturates or the pet targets the edge, add overlap or change the routine.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Listing fit','body','The checked variant is 27.5 x 44 inches and includes a runoff barrier edge; confirm pack count before checkout.'),JSON_OBJECT('title','Placement test','body','Lay it flat, absorbent side up, and observe where the dog actually steps and squats.'),JSON_OBJECT('title','Cost check','body','Compare weekly events and cleaner/laundry cost, not only the package price.'),JSON_OBJECT('title','Alternative','body','Use a washable mat for tracking or outdoor breaks when the problem is not liquid containment.')),'alternatives',JSON_ARRAY('Drymate washable litter mat','Outdoor potty routine'),'evidenceNote','Dimensions and feature claims are tied to the checked Amazon variant; pack count and price are dynamic.') WHERE slug='best-large-dog-training-pad';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A padded walking harness with four adjustment points, two leash attachments, and reflective trim in the checked Basalt Gray X-Small variant.','notFor','Dogs whose body shape allows backing out, an unmeasured size, or unsupervised vehicle restraint.','decision',JSON_OBJECT('headline','Fit is the actual feature','summary','Comfort and visibility only help when the exact size stays aligned through movement.','criteria',JSON_ARRAY('Chest measurement','Two-finger clearance','No elbow rub or backing out'),'boundary','Stop outdoor use until the harness is refit if it shifts, rubs, or permits escape.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Variant fit','body','The checked listing is Basalt Gray X-Small; do not generalize its fit to larger dogs.'),JSON_OBJECT('title','Adjustment sequence','body','Set chest and neck straps evenly, then test walking and a gentle supervised backing-out motion indoors.'),JSON_OBJECT('title','Visibility and control','body','Reflective trim helps low light, while the two attachment points should match the intended leash setup.'),JSON_OBJECT('title','Alternative','body','Compare Julius-K9 for a back handle or Kurgo when travel is part of the routine.')),'alternatives',JSON_ARRAY('Julius-K9 IDC Powerharness','Kurgo Enhanced Strength Tru-Fit'),'evidenceNote','Variant identity and listed features are checked on Amazon.com; current size charts and travel instructions remain authoritative.') WHERE slug='best-everyday-dog-harness';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A focused large-dog, long-hair undercoat tool with a clear weekly-use boundary.','notFor','Matted coats, close trimming, or pets that cannot tolerate brushing.','decision',JSON_OBJECT('headline','Pick by coat problem, not shedding promises','summary','The listing supports loose-undercoat removal, not detangling or clipping.','criteria',JSON_ARRAY('Correct size and coat length','Light pressure and short sessions','Skin tolerance and stop point'),'boundary','If the coat is matted near skin or the pet reacts, stop and use professional help.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Shortlist reason','body','The checked ASIN is a large-dog, long-hair variant for weekly de-shedding.'),JSON_OBJECT('title','Decision check','body','Compare weight, coat length, and tolerance before comparing claims.'),JSON_OBJECT('title','Ownership','body','Use on a clean, dry coat; remove collected hair and inspect skin afterward.'),JSON_OBJECT('title','Alternative','body','Choose a clipper for length control or a gentle brush for detangling.')),'alternatives',JSON_ARRAY('A coat-length clipper','A soft detangling brush'),'evidenceNote','Amazon identity and image are verified; price, stock, seller, and review count are dynamic.') WHERE slug='best-de-shedding-tool';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A dedicated indoor pail for households that scoop litter daily and want fewer trips outside.','notFor','Homes unwilling to buy refill film or households whose main problem is liquid floor coverage.','decision',JSON_OBJECT('headline','Choose the waste workflow first','summary','Capacity varies with cat count, clump size, and emptying cadence.','criteria',JSON_ARRAY('Number of cats','Refill availability and cost','Odor and emptying routine'),'boundary','If refill film is unavailable or the room needs leak protection, choose another format.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Listing fit','body','The checked standard pail includes a 14 ft refill and states up to 14 days for one cat.'),JSON_OBJECT('title','Capacity plan','body','Track a normal week and set an emptying reminder; do not treat headline capacity as a guarantee.'),JSON_OBJECT('title','Odor routine','body','Push waste below the seal, close the chute, and wipe the rim.'),JSON_OBJECT('title','Alternative','body','Use sealed disposable bags for portable cleanup or a normal lidded bin when refill film is impractical.')),'alternatives',JSON_ARRAY('Disposable litter bags','A lidded household waste bin'),'evidenceNote','Identity is verified; refill price, stock, and capacity claims must be checked live.') WHERE slug='best-indoor-litter-waste-pail';
UPDATE best_picks SET content_json=JSON_OBJECT('why','The checked Kurgo variant combines walking and vehicle-use context with a Large fit boundary and steel hardware.','notFor','Unsupervised vehicle restraint, a guessed size, or a setup not tested while parked.','decision',JSON_OBJECT('headline','Separate walking fit from travel setup','summary','A travel-capable listing still needs exact size, attachment path, and current instructions.','criteria',JSON_ARRAY('Chest measurement and variant','Designated vehicle attachment','Stationary fit and movement check'),'boundary','Do not drive until correctly installed and tested while parked.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Listing fit','body','The checked black Large listing states a seatbelt tether, steel carabiner, all-steel buckles, padded chest, and a dog weight claim up to 75 lb.'),JSON_OBJECT('title','Fit before features','body','A harness that rubs, restricts movement, or allows backing out is not a good fit.'),JSON_OBJECT('title','Travel preflight','body','Check tether route, buckles, clip, and movement while parked.'),JSON_OBJECT('title','Alternative','body','Choose a walking-first harness or a secured crate when the vehicle routine calls for it.')),'alternatives',JSON_ARRAY('A walking-first padded harness','A secured travel crate'),'evidenceNote','Variant identity and listing facts are verified; current fit guidance and vehicle instructions remain authoritative.') WHERE slug='best-walk-and-travel-harness';

UPDATE guides SET content_json=JSON_OBJECT('summary','Choose a clipper by coat, handling skill, noise tolerance, and maintenance routine rather than motor marketing alone.','takeaways',JSON_ARRAY('Identify coat and mat boundaries','Compare guards and blade adjustment','Plan heat and noise breaks','Budget for parts'),'sections',JSON_ARRAY(JSON_OBJECT('title','Start with the coat','body','Thick, matted, curly, and fine coats need different strategies; mats close to skin are a stop condition.'),JSON_OBJECT('title','Compare control','table',JSON_ARRAY(JSON_OBJECT('item','Guards','check','Repeatable home length'),JSON_OBJECT('item','Adjustable blade','check','Finer control versus maintenance'),JSON_OBJECT('item','Noise and heat','check','Can the pet stay calm?'))),JSON_OBJECT('title','First session','checklist',JSON_ARRAY('Charge and inspect','Run away from pet','Make short passes','Check skin and temperature')),JSON_OBJECT('title','Stop point','body','Pulling, heat, damaged hardware, irritation, or escalating fear calls for a pause and possibly professional help.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Is higher power always better?','a','No. Control, heat, coat condition, and tolerance decide fit.'),JSON_OBJECT('q','What needs maintenance?','a','Clean and oil blades as directed, charge safely, and plan for replacements.'),JSON_OBJECT('q','Can I clip tight mats?','a','Do not assume so; tight mats can hide skin and need professional handling.')),'sourceNote','Product claims are scoped to checked Amazon listings; coat and skin safety needs qualified advice.') WHERE slug='choose-a-pet-clipper-by-coat-and-temperament';
UPDATE guides SET content_json=JSON_OBJECT('summary','Lower mess comes from matching containment, placement, disposal, and cleaning cadence to the actual waste event.','takeaways',JSON_ARRAY('Name the failure','Measure a normal week','Keep supplies nearby','Use a backup format'),'sections',JSON_ARRAY(JSON_OBJECT('title','Name the failure','bullets',JSON_ARRAY('Liquid leakage needs coverage.','Tracking needs a mat.','Odor needs sealing and cadence.','Overflow needs capacity planning.')),JSON_OBJECT('title','Measure','body','Track pads, bags, scoops, refill film, cleaner, and time for seven days.'),JSON_OBJECT('title','Build the station','checklist',JSON_ARRAY('Keep spares nearby','Place a bin at the exit','Add a washable backup','Set a refill reminder')),JSON_OBJECT('title','Review','body','If the failure remains, change the format or placement instead of buying a larger version of the wrong product.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Does odor wording guarantee no odor?','a','No. Seals, cadence, cleaning, and room temperature matter.'),JSON_OBJECT('q','Is one format best for every pet?','a','No; liquid, litter, tracking, and outdoor walks differ.'),JSON_OBJECT('q','Should I keep a backup?','a','A spare roll or pack prevents a delayed delivery becoming a floor problem.')),'sourceNote','Dimensions and features come from checked Amazon listings; prices and pack counts change.') WHERE slug='build-a-lower-mess-pet-cleanup-routine';
UPDATE guides SET content_json=JSON_OBJECT('summary','A reliable harness fit starts with measurement, even adjustment, movement checks, and a supervised failure-mode test.','takeaways',JSON_ARRAY('Use the current size chart','Measure chest girth','Check elbows and throat','Test backing out indoors'),'sections',JSON_ARRAY(JSON_OBJECT('title','Measure twice','body','Record chest girth and weight guidance against the exact maker chart and variant.'),JSON_OBJECT('title','Adjust evenly','checklist',JSON_ARRAY('Two fingers under straps','No elbow rub','Throat clear','Shoulders move freely')),JSON_OBJECT('title','Test movement','body','Walk, sit, and turn indoors while watching for rotation or restriction.'),JSON_OBJECT('title','Test failure mode','body','Supervise a gentle backing-out check; if the dog can escape, do not use the fit outdoors.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Is two-finger clearance universal?','a','It is a starting check; the current chart and movement govern.'),JSON_OBJECT('q','Should I size up for comfort?','a','Not automatically; excess slack can create rubbing or escape risk.'),JSON_OBJECT('q','Can any harness be used in a car?','a','Only when the exact model instructions document it.')),'sourceNote','Size facts are tied to checked Amazon variants; fit must be tested on the actual dog.') WHERE slug='measure-and-fit-a-dog-harness';
UPDATE guides SET content_json=JSON_OBJECT('summary','Estimate cleanup from real events, then add leakage, refill delays, and cleaning time instead of comparing package headlines.','takeaways',JSON_ARRAY('Count a normal week','Separate liquid, solid, and tracking','Include recurring supplies','Set a refill trigger'),'sections',JSON_ARRAY(JSON_OBJECT('title','Count events','body','Record pads, bags, scoops, and wash cycles for seven normal days.'),JSON_OBJECT('title','Add failure cost','table',JSON_ARRAY(JSON_OBJECT('item','Leakage','check','Cleaner and laundry'),JSON_OBJECT('item','Refill delay','check','Backup roll or pack'),JSON_OBJECT('item','Odor','check','Earlier emptying'))),JSON_OBJECT('title','Compare formats','body','A washable mat does not contain scooped waste; a pail does not absorb floor accidents.'),JSON_OBJECT('title','Set a trigger','checklist',JSON_ARRAY('Keep one backup','Check delivery time','Review after pet-count changes'))),'faq',JSON_ARRAY(JSON_OBJECT('q','Compare package price?','a','Use cost per week or event; pack sizes differ.'),JSON_OBJECT('q','What changes with multiple pets?','a','Scoops, bags, pads, and emptying frequency rise.'),JSON_OBJECT('q','Cheapest format?','a','The best value prevents the failure you actually have.')),'sourceNote','Dimensions and feature claims are tied to checked Amazon listings; prices and availability are dynamic.') WHERE slug='pet-waste-cost-and-capacity-planner';
UPDATE guides SET content_json=JSON_OBJECT('summary','A two-minute check of fit, clips, leash, visibility, ID, and route catches preventable failures before a walk.','takeaways',JSON_ARRAY('Fit before leaving','Inspect load-bearing connections','Carry ID and a backup','Adjust for route and weather'),'sections',JSON_ARRAY(JSON_OBJECT('title','Pet fit','checklist',JSON_ARRAY('Two-finger strap check','No elbow rubbing','Normal breathing','Current ID')),JSON_OBJECT('title','Equipment','checklist',JSON_ARRAY('Buckle closed','Clip gate closes','Stitching intact','Reflective area or light visible')),JSON_OBJECT('title','Route','body','Carry water, waste bags, and a light; know what to do if the dog slips the fit or traffic changes.'),JSON_OBJECT('title','Vehicle transition','body','A walking harness is not automatically a crash restraint; use only the documented attachment.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Is reflective trim enough?','a','No. Add a light at night.'),JSON_OBJECT('q','How often inspect clips?','a','Before every walk and after unusual loads.'),JSON_OBJECT('q','Can any harness be used in a car?','a','Only when exact instructions document it.')),'sourceNote','Variant and feature facts come from checked Amazon listings; current instructions govern fit and travel safety.') WHERE slug='dog-walk-safety-preflight';
UPDATE guides SET content_json=JSON_OBJECT('summary','Estimate cleanup from real events, then add leakage, refill delays, and cleaning time instead of comparing package headlines alone.','takeaways',JSON_ARRAY('Count normal use','Separate waste moments','Include recurring supplies','Keep a backup'),'sections',JSON_ARRAY(JSON_OBJECT('title','Count events','body','Use a seven-day baseline for pads, bags, scoops, and mat washes.'),JSON_OBJECT('title','Compare failure costs','body','Include leaks, cleaner, laundry, refill film, and emergency purchases.'),JSON_OBJECT('title','Choose a format','body','Match pads, mats, bags, or pails to the specific failure rather than a broad odor promise.'),JSON_OBJECT('title','Review monthly','body','Recalculate after a pet-count, diet, or delivery change.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Why not compare pack price?','a','Pack counts and sizes differ; weekly use is more honest.'),JSON_OBJECT('q','Do reusable products always cost less?','a','Only when wash time and replacement life fit the routine.'),JSON_OBJECT('q','What is a sensible backup?','a','One spare roll or pack for the next delayed delivery.')),'sourceNote','Feature and dimension facts are tied to checked Amazon listings; dynamic prices must be checked live.') WHERE slug='pet-waste-cost-and-capacity-planner';

UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Stop if the blade is hot, jammed, damaged, or the pet is distressed.','intro','Pulling usually means hair intake, coat condition, heat, or technique needs to change.','quickChecks',JSON_ARRAY('Turn off and clear hair','Check for mats','Inspect blade and guard','Let it cool'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Clear and cool','instruction','Turn off, remove trapped hair, and cool the blade.','why','Heat and jams increase pulling and skin risk.','result','Tool moves freely.'),JSON_OBJECT('title','Change the pass','instruction','Brush first and take shorter guarded passes.','why','Less intake reduces stalls.','result','Coat feeds evenly.'),JSON_OBJECT('title','Maintain','instruction','Clean and lubricate as directed; replace damaged parts.','why','Buildup and dull edges pull.','result','Blade and guard are intact.'),JSON_OBJECT('title','Escalate','instruction','Stop for tight mats, irritation, repeated stalls, or distress and contact a groomer.','why','Technique cannot make every coat safe.','result','Pet avoids injury.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Pulling every pass','cause','Mat or dull blade','next','Stop and inspect'),JSON_OBJECT('observation','Stalls','cause','Buildup or heat','next','Clear and cool'),JSON_OBJECT('observation','Flinch','cause','Heat, noise, or snagging','next','Stop and acclimate')),'support','Use current Oneisall instructions and qualified grooming help when uncertain.','supportChecklist',JSON_ARRAY('Record guard','Note coat condition','Keep ASIN and date'),'faq',JSON_ARRAY(JSON_OBJECT('q','Can oil fix a mat?','a','No; oil supports maintenance, not mat removal.'),JSON_OBJECT('q','How often cool?','a','Check frequently and whenever discomfort appears.'),JSON_OBJECT('q','Keep going after a stall?','a','No; turn off, clear, and reassess.')),'sourceNote','Tool facts come from the checked Amazon listing; coat and skin problems need professional judgment.') WHERE slug='pet-clipper-pulling-hair';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Clean urine promptly, keep pets away from wet cleaning products, and wash hands after cleanup.','intro','Leaks come from orientation, placement, saturation, overlap, or edge use.','quickChecks',JSON_ARRAY('Absorbent side up','Pad flat','Target centered','Replace before saturation'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Orient','instruction','Place absorbent surface up with backing flat and edge unfolded.','why','Folded or reversed pads lose coverage.','result','Pad is smooth.'),JSON_OBJECT('title','Move target','instruction','Observe where the dog stands and add overlap if needed.','why','Large pads still fail off-center.','result','Events land away from edge.'),JSON_OBJECT('title','Replace','instruction','Change before saturation and clean below.','why','Saturation causes secondary leaks.','result','Floor stays dry.'),JSON_OBJECT('title','Review format','instruction','If edge use continues, add a tray or seek behavioral/medical advice for sudden changes.','why','A pad cannot solve every cause.','result','Routine matches problem.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Edge leak','cause','Placement or edge use','next','Center and overlap'),JSON_OBJECT('observation','After several events','cause','Saturation','next','Replace earlier'),JSON_OBJECT('observation','Dog avoids pad','cause','Location or texture','next','Move and train positively')),'support','Sudden accident changes with illness signs need veterinary advice.','supportChecklist',JSON_ARRAY('Record pad size','Note events/day','Photograph damage if needed'),'faq',JSON_ARRAY(JSON_OBJECT('q','Does XXL mean leak-proof?','a','No; coverage and placement still control results.'),JSON_OBJECT('q','Reuse disposable pads?','a','Follow product design; reuse can worsen hygiene and leaks.'),JSON_OBJECT('q','Dog targets edge?','a','Add overlap/tray or reassess placement.')),'sourceNote','Size and barrier facts are scoped to the checked Amazon listing; health changes require support.') WHERE slug='training-pad-leaking';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Use backup identification and control while fit is uncertain; stop outdoor use if the harness rubs or permits escape.','intro','Rubbing and slipping are fit signals. Adjust evenly, check movement, and test the escape boundary indoors.','quickChecks',JSON_ARRAY('Measure against chart','Two-finger clearance','Clear elbows and throat','Supervise backing-out'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Reset straps','instruction','Loosen and refit neck and chest straps evenly.','why','One loose strap rotates the harness.','result','Harness sits centered.'),JSON_OBJECT('title','Check movement','instruction','Walk, sit, turn, and inspect elbows and throat.','why','Static fit can hide rubbing.','result','Movement is free.'),JSON_OBJECT('title','Test backing out','instruction','Apply gentle supervised backward pressure in a safe room.','why','Body shape can defeat snug fit.','result','Dog cannot escape.'),JSON_OBJECT('title','Change course','instruction','Stop outdoor use and contact the maker or fitter if it persists.','why','Persistent failure is a fit mismatch.','result','Safer fit selected.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Elbow rubbing','cause','Strap low or loose','next','Refit'),JSON_OBJECT('observation','Rotates','cause','Uneven adjustment','next','Center and tighten'),JSON_OBJECT('observation','Backs out','cause','Body shape boundary','next','Choose different fit')),'support','Keep the current Ruffwear size chart and variant details for support.','supportChecklist',JSON_ARRAY('Record chest measurement','Keep exact variant','Photograph routing'),'faq',JSON_ARRAY(JSON_OBJECT('q','Is two-finger clearance enough?','a','It is a starting check; movement and escape testing matter.'),JSON_OBJECT('q','Tighten until immobile?','a','No; breathing and shoulder movement must remain normal.'),JSON_OBJECT('q','Does reflective trim prevent escape?','a','No; visibility and fit solve different problems.')),'sourceNote','Variant and adjustment facts come from the checked Amazon listing; the actual dog determines fit.') WHERE slug='dog-harness-rubs-or-slips';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Stop at distress, bleeding, a cracked nail, or a damaged guard.','intro','Vibration reactions improve through acclimation and shorter contact, not pressing harder.','quickChecks',JSON_ARRAY('Run motor away','Inspect guard and band','Confirm speed and bit','Check cracked nail'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Build sound tolerance','instruction','Run nearby briefly, reward calm, and stop before escalation.','why','Sound may trigger fear before contact.','result','Pet remains relaxed.'),JSON_OBJECT('title','Check contact surface','instruction','Remove buildup and replace a worn band.','why','Damage increases heat and vibration.','result','Tool runs smoothly.'),JSON_OBJECT('title','Use one-second contacts','instruction','Touch one nail briefly, reward, and end if the pet withdraws.','why','Short exposures reduce heat.','result','Nail shortens gradually.'),JSON_OBJECT('title','Escalate','instruction','Stop for bleeding, cracks, pain, or repeated distress and contact a professional.','why','Technique cannot solve injury or severe fear.','result','Appropriate care.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','React before contact','cause','Sound sensitivity','next','Sound-only acclimation'),JSON_OBJECT('observation','Rough tool','cause','Worn band','next','Clean or replace'),JSON_OBJECT('observation','Bleeding','cause','Quick reached','next','Stop and seek advice')),'support','Use current Dremel instructions or a qualified groomer.','supportChecklist',JSON_ARRAY('Record ASIN and bit','Note speed','Record distress/bleeding'),'faq',JSON_ARRAY(JSON_OBJECT('q','Hold paw tighter?','a','No; restraint can increase fear and injury.'),JSON_OBJECT('q','Finish all nails?','a','Only if the pet stays calm.'),JSON_OBJECT('q','Abnormal motor sound?','a','Stop and inspect; do not use damaged equipment.')),'sourceNote','Product facts are from the checked Amazon listing; injury and behavior need qualified help.') WHERE slug='dremel-pawcontrol-vibration-too-high';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Wash hands after waste handling, keep pail inaccessible, and do not reach into a jammed chute.','intro','Odor usually points to a seal, overfill, refill, or cleaning routine issue.','quickChecks',JSON_ARRAY('Refill seated','Waste below seal','Below fill line','Rim clean'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Reseat refill','instruction','Confirm standard film is seated and cutter closes.','why','Loose film bypasses the seal.','result','Lid closes without gaps.'),JSON_OBJECT('title','Reset drop routine','instruction','Push each scoop below the seal and close the chute.','why','Waste above seal releases odor.','result','Chute clear.'),JSON_OBJECT('title','Empty earlier','instruction','Use a shorter cadence for multiple cats or large clumps.','why','Capacity is a one-cat listing claim.','result','Below overfill.'),JSON_OBJECT('title','Clean surfaces','instruction','Wipe rim and lid with pet-safe cleaner and dry.','why','Residue holds odor.','result','Seal area clean.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','After refill','cause','Film not seated','next','Reseat'),JSON_OBJECT('observation','When full','cause','Overfill','next','Empty earlier'),JSON_OBJECT('observation','Empty but smells','cause','Residue','next','Clean and dry')),'support','If seal or cutter is damaged, consult current Litter Genie instructions.','supportChecklist',JSON_ARRAY('Record refill type','Note cat count','Photograph damage'),'faq',JSON_ARRAY(JSON_OBJECT('q','Eliminate odor?','a','No; it contains waste when used and maintained.'),JSON_OBJECT('q','Any refill?','a','Use the format specified for the pail.'),JSON_OBJECT('q','How often empty?','a','Use actual cat count and clump volume.')),'sourceNote','Capacity and refill facts are scoped to the checked Amazon listing; current instructions control.') WHERE slug='litter-genie-odor-escaping';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Do not use an unfamiliar restraint on a moving vehicle; park first and follow current Kurgo instructions.','intro','A twisted clip is usually a routing or fit problem, not a reason to improvise an attachment.','quickChecks',JSON_ARRAY('Park first','Identify vehicle point','Check orientation and fit','Test while parked'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Stop and park','instruction','Move to a safe parked position before inspecting.','why','Never adjust while driving.','result','Pet and vehicle stationary.'),JSON_OBJECT('title','Confirm path','instruction','Match tether and carabiner to the designated vehicle point.','why','A leash point may not be the travel path.','result','No twisting or rubbing.'),JSON_OBJECT('title','Recheck fit','instruction','Verify chest strap, buckles, throat clearance, and backing-out resistance.','why','Poor fit rotates the harness.','result','Harness aligned.'),JSON_OBJECT('title','Test','instruction','Allow normal sitting and standing while parked, then recheck connections.','why','Stationary testing catches rotation.','result','Setup stays secure.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Clip rotates','cause','Routing error','next','Follow attachment path'),JSON_OBJECT('observation','Shifts sideways','cause','Loose fit','next','Remeasure'),JSON_OBJECT('observation','Backs toward opening','cause','Body shape','next','Stop travel and refit')),'support','If hardware does not match instructions, contact manufacturer before driving.','supportChecklist',JSON_ARRAY('Record ASIN and size','Keep manual nearby','Test parked'),'faq',JSON_ARRAY(JSON_OBJECT('q','Any metal ring?','a','No; use the documented point.'),JSON_OBJECT('q','Automatically crash tested?','a','No; confirm exact product and claim.'),JSON_OBJECT('q','Dog can back out?','a','Do not drive; refit or change setup.')),'sourceNote','Vehicle-use claims and variant details are tied to the checked Amazon listing; manufacturer instructions are authoritative.') WHERE slug='kurgo-harness-car-clip-twists';
